public static class RefineLuigiPlayUI {
 const string Sheet="Assets/Art/UI/Sprites/Common/LuigiPlayKit.png",Parts="Assets/Art/UI/Prefabs/Parts/",FontRoot="Assets/Art/Fonts/";
 static readonly Vector2 C=new Vector2(.5f,.5f),TL=new Vector2(0,1),TR=Vector2.one,TC=new Vector2(.5f,1),BC=new Vector2(.5f,0);
 static Sprite S(string name)=>new[]{Sheet,"Assets/Art/UI/Sprites/Common/LuigiMenuKit.png","Assets/Art/UI/Sprites/Common/LuigiMenuBook.png","Assets/Art/UI/Sprites/Common/LuigiHudTrim.png"}.SelectMany(AssetDatabase.LoadAllAssetsAtPath).OfType<Sprite>().First(x=>x.name==name);
 public static string Main(){Slice();Edit(Parts+"UIMakingCard.prefab",Making);Edit(Parts+"UICompletionGauge.prefab",Gauge);Edit(Parts+"UIStandingRow.prefab",Standing);Edit(Parts+"UIRecipeRow.prefab",Recipe);Edit(Parts+"UINamedItemIcon.prefab",NamedIcon);Edit("Assets/Art/UI/Prefabs/Screen/UIMatchHudScreen.prefab",Hud);return "HUD Common/Day/Night preserved; shared manufacturing, timing, recipe and standing parts refined in place.";}
 static void Edit(string path,Action<GameObject> action){var root=PrefabUtility.LoadPrefabContents(path);try{action(root);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
 static void Slice(){
  AssetDatabase.ImportAsset(Sheet,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(Sheet);ti.textureType=TextureImporterType.Sprite;ti.spriteImportMode=SpriteImportMode.Multiple;ti.spritePixelsPerUnit=100;ti.alphaIsTransparency=true;ti.mipmapEnabled=false;ti.npotScale=TextureImporterNPOTScale.None;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();
  var factories=new SpriteDataProviderFactories();factories.Init();var provider=factories.GetSpriteEditorDataProviderFromObject(ti);provider.InitSpriteEditorDataProvider();var cap=provider.GetDataProvider<ISpriteFrameEditCapability>();if(cap==null)throw new Exception("No Sprite capability");foreach(var c in new[]{EEditCapability.CreateAndDeleteSprite,EEditCapability.EditBorder,EEditCapability.EditPivot,EEditCapability.EditSpriteRect})if(!cap.GetEditCapability().HasCapability(c))throw new Exception("Unsupported "+c);
  var tex=new Texture2D(2,2);tex.LoadImage(File.ReadAllBytes(Sheet));var pixels=tex.GetPixels32();var cells=new[]{new RectInt(0,0,480,780),new RectInt(480,0,774,780),new RectInt(0,780,390,474),new RectInt(390,780,864,474)};var names=new[]{"PlayClipboard","PlayBoard","PlayClock","PlayTiming"};var before=provider.GetSpriteRects();var rects=new System.Collections.Generic.List<SpriteRect>();
  for(int i=0;i<cells.Length;i++){var cell=cells[i];int x0=tex.width,y0=tex.height,x1=0,y1=0;for(int y=cell.y;y<Math.Min(tex.height,cell.yMax);y++)for(int x=cell.x;x<Math.Min(tex.width,cell.xMax);x++)if(pixels[(tex.height-1-y)*tex.width+x].a>48){x0=Math.Min(x0,x);y0=Math.Min(y0,y);x1=Math.Max(x1,x);y1=Math.Max(y1,y);}var old=before.FirstOrDefault(x=>x.name==names[i]);rects.Add(new SpriteRect{name=names[i],spriteID=old!=null?old.spriteID:GUID.Generate(),rect=new Rect(x0,tex.height-y1-1,x1-x0+1,y1-y0+1),border=i==1?new Vector4(65,65,65,65):i==0?new Vector4(40,45,40,140):Vector4.zero,pivot=C,alignment=SpriteAlignment.Center});}
  provider.SetSpriteRects(rects.ToArray());var idProvider=provider.GetDataProvider<ISpriteNameFileIdDataProvider>();if(idProvider==null)throw new Exception("No Sprite file IDs");idProvider.SetNameFileIdPairs(rects.Select(r=>new SpriteNameFileIdPair(r.name,r.spriteID)));provider.Apply();ti.SaveAndReimport();Object.DestroyImmediate(tex);
