 static T Ref<T>(Object owner,string name)where T:Object=>new SerializedObject(owner).FindProperty(name).objectReferenceValue as T;
 static void Wire(Object owner,string name,Object value){var so=new SerializedObject(owner);so.FindProperty(name).objectReferenceValue=value;so.ApplyModifiedPropertiesWithoutUndo();}
 static RectTransform F(Transform r,string p)=>r.Find(p) as RectTransform??throw new Exception(r.name+" missing "+p);
 static RectTransform New(Transform p,string n){var r=p.Find(n) as RectTransform;if(r!=null)return r;var g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(p,false);return (RectTransform)g.transform;}
 static void Place(Transform t,Vector2 a,float x,float y,float w,float h,Vector2? pivot=null){var r=(RectTransform)t;r.anchorMin=r.anchorMax=a;r.pivot=pivot??C;r.anchoredPosition=new Vector2(x,y);r.sizeDelta=new Vector2(w,h);r.localScale=Vector3.one;}
 static void Stretch(Transform t,float l=0,float top=0,float r=0,float b=0){var rt=(RectTransform)t;rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.pivot=C;rt.offsetMin=new Vector2(l,b);rt.offsetMax=new Vector2(-r,-top);rt.localScale=Vector3.one;}
 static void Free(Transform t){foreach(var l in t.GetComponents<LayoutGroup>())l.enabled=false;var f=t.GetComponent<ContentSizeFitter>();if(f!=null)f.enabled=false;}
 static TMP_Text Text(Transform r,float size,bool ink=false,string role="Title",TextAlignmentOptions align=TextAlignmentOptions.MidlineLeft){var t=r.GetComponent<TMP_Text>();t.font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FontRoot+"Luigi"+role+" SDF.asset");t.fontSharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(FontRoot+"LuigiMenu"+role+(ink?"Ink":"Light")+".mat");t.enableVertexGradient=false;t.color=ink?new Color(.16f,.085f,.035f):new Color(1,.95f,.81f);t.fontSize=size;t.enableAutoSizing=false;t.alignment=align;t.textWrappingMode=TextWrappingModes.NoWrap;return t;}
 static TMP_Text Label(Transform parent,string n,string value,float size,bool ink=false,string role="Title"){var r=New(parent,n);if(r.GetComponent<TextMeshProUGUI>()==null)r.gameObject.AddComponent<TextMeshProUGUI>();var text=Text(r,size,ink,role,TextAlignmentOptions.Center);text.text=value;text.raycastTarget=false;return text;}
 static Image Face(Transform t,string sprite,bool sliced=true){var old=t.Cast<Transform>().Select(x=>x.GetComponent<UISurfacePart>()).FirstOrDefault(x=>x!=null);Image im;if(old==null){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Parts+"UISurfacePart.prefab"));g.name="LuigiSurface";g.transform.SetParent(t,false);g.transform.SetAsFirstSibling();im=g.GetComponent<Image>();}else im=old.Graphic;Stretch(im.transform);im.GetComponent<LayoutElement>().ignoreLayout=true;im.sprite=S(sprite);im.type=sliced?Image.Type.Sliced:Image.Type.Simple;im.color=Color.white;im.fillCenter=true;im.pixelsPerUnitMultiplier=3;im.raycastTarget=false;return im;}
 static void Fonts(GameObject root){foreach(var t in root.GetComponentsInChildren<TMP_Text>(true)){if(t.font==null)continue;var role=t.font.name.Contains("Number")?"Number":t.font.name.Contains("Body")?"Body":"Title";var ink=t.fontSharedMaterial!=null&&t.fontSharedMaterial.name.Contains("Ink");Text(t.transform,t.fontSize,ink,role,t.alignment);}}
 static void Hud(GameObject root){
  Fonts(root);var g=root.transform;var day=root.GetComponentInChildren<UIMatchHudDay>(true);var night=root.GetComponentInChildren<UIMatchHudNight>(true);
  var ranking=F(g,"DayRoot/DayHeader/TeamStandings");Place(ranking,TL,24,-24,262,226,TL);Face(ranking,"PlayBoard").pixelsPerUnitMultiplier=3;
  var layout=ranking.GetComponent<VerticalLayoutGroup>();layout.padding=new RectOffset(14,14,16,16);layout.spacing=5;layout.childForceExpandHeight=false;
  foreach(var row in ranking.GetComponentsInChildren<UIStandingRow>(true)){var rt=(RectTransform)row.transform;var e=row.GetComponent<LayoutElement>()??row.gameObject.AddComponent<LayoutElement>();e.preferredHeight=e.minHeight=44;foreach(var f in row.GetComponentsInChildren<UISurfacePart>()){f.Graphic.sprite=S("LuigiRowPlaque");f.Graphic.type=Image.Type.Sliced;f.Graphic.pixelsPerUnitMultiplier=10;f.Graphic.fillCenter=false;f.GetComponent<LayoutElement>().ignoreLayout=true;}foreach(var t in row.GetComponentsInChildren<TMP_Text>())Text(t.transform,t.name=="Total"?26:22,false,t.name=="Total"||t.name=="Rank"?"Number":"Title",t.alignment);}
  var clock=F(g,"DayRoot/DayHeader/ClockBadge");Place(clock,TC,0,-18,450,92,TC);Face(clock,"LuigiTimerPlaque",false);var alarm=clock.Find("AlarmClock");if(alarm!=null)alarm.gameObject.SetActive(false);
  Place(Ref<TMP_Text>(day,"dayClock").transform,C,-12,4,185,72);Text(Ref<TMP_Text>(day,"dayClock").transform,57,false,"Number",TextAlignmentOptions.Center);Place(Ref<TMP_Text>(day,"dayCounter").transform,TR,-28,-20,112,50,TR);Text(Ref<TMP_Text>(day,"dayCounter").transform,29,false,"Title",TextAlignmentOptions.Center);F(clock,"DayLabel").gameObject.SetActive(false);F(clock,"TimeGauge").gameObject.SetActive(false);
  var sales=F(g,"DayRoot/DayHeader/SalesBlock");Place(sales,TR,-24,-24,330,115,TR);Place(Ref<TMP_Text>(day,"dayRevenue").transform,TL,75,-21,102,48,TL);Text(Ref<TMP_Text>(day,"dayRevenue").transform,43,false,"Number",TextAlignmentOptions.Right);Place(Ref<TMP_Text>(day,"dayGoal").transform,TR,-30,-21,102,48,TR);Text(Ref<TMP_Text>(day,"dayGoal").transform,39,false,"Number",TextAlignmentOptions.Right);var slash=Label(sales,"SalesSeparator","/",35);Place(slash.transform,TL,182,-21,30,48,TL);F(sales,"Label").gameObject.SetActive(false);F(sales,"GoalLabel").gameObject.SetActive(false);var caption=F(sales,"SalesCaptionPlate");Place(caption,BC,0,7,195,38);foreach(var t in caption.GetComponentsInChildren<TMP_Text>())Text(t.transform,22,false,"Title",TextAlignmentOptions.Center);
