  var summary=Ref<RectTransform>(night,"nightBagSummaryRoot");Place(summary,new Vector2(0,0),0,-11,242,48,new Vector2(0,1));var weight=Ref<TMP_Text>(night,"nightBagSummary");Place(weight.transform,TR,-10,-8,157,33,TR);Text(weight.transform,19,false,"Number",TextAlignmentOptions.Right);
  var header=F(g,"NightRoot/TopCenter");Place(header,TC,0,-16,290,56,TC);var bag=Ref<RectTransform>(night,"nightBagDock");Place(bag,new Vector2(1,0),-26,26,263,64,new Vector2(1,0));Text(Ref<TMP_Text>(night,"bagWeightText").transform,26,false,"Number",TextAlignmentOptions.Right);
  var salesCaption=F(sales,"Label");salesCaption.gameObject.SetActive(true);Place(salesCaption,BC,0,10,185,32);Text(salesCaption,22,false,"Title",TextAlignmentOptions.Center);
  foreach(var row in ranking.GetComponentsInChildren<UIStandingRow>(true)){var so=new SerializedObject(row);so.FindProperty("ownTeamName").stringValue="";var labels=so.FindProperty("teamNames");labels.arraySize=4;for(int i=0;i<4;i++)labels.GetArrayElementAtIndex(i).stringValue="팀 "+(i+1);so.ApplyModifiedPropertiesWithoutUndo();}
