 static void Making(GameObject root){
  Fonts(root);var card=root.GetComponent<UIMakingCard>();root.GetComponent<Image>().color=Color.clear;((RectTransform)root.transform).sizeDelta=new Vector2(228,344);var body=F(root.transform,"Body");Stretch(body);body.GetComponent<Image>().color=Color.clear;Face(body,"PlayClipboard",false);F(root.transform,"ClipboardClip").gameObject.SetActive(false);var header=F(body,"Header");Stretch(header);Free(header);var texts=F(header,"Texts");Stretch(texts);Free(texts);var nameRow=F(texts,"NameRow");Free(nameRow);Place(nameRow,TC,0,-90,188,33,TC);Place(Ref<TMP_Text>(card,"nameText").transform,C,0,0,180,32);Text(Ref<TMP_Text>(card,"nameText").transform,21,true,"Title",TextAlignmentOptions.Center);
  var status=Ref<TMP_Text>(card,"statusText");Place(status.transform,TC,0,-52,183,30,TC);Text(status.transform,22,true,"Title",TextAlignmentOptions.Center);var oldPlate=status.transform.Find("StatePlate");if(oldPlate!=null)oldPlate.SetParent(texts,false);var plate=New(texts,"StatePlate");Place(plate,TC,0,-50,189,34,TC);plate.SetAsFirstSibling();var pi=plate.GetComponent<Image>()??plate.gameObject.AddComponent<Image>();pi.sprite=S("MenuCream");pi.type=Image.Type.Sliced;pi.pixelsPerUnitMultiplier=9;pi.raycastTarget=false;Wire(card,"frame",pi);Ref<Image>(card,"glow").sprite=S("PlayClipboard");Ref<Image>(card,"glow").type=Image.Type.Simple;
