 }
 static void Gauge(GameObject root){Fonts(root);((RectTransform)root.transform).sizeDelta=new Vector2(530,138);Face(root.transform,"PlayTiming",false);var gauge=root.GetComponent<UICompletionGauge>();var bar=Ref<RectTransform>(gauge,"bar");Place(bar,C,0,-4,456,30);bar.GetComponent<Image>().color=new Color(.78f,.08f,.13f);foreach(var n in new[]{"good","perfect"}){var zone=Ref<RectTransform>(gauge,n);zone.sizeDelta=new Vector2(zone.sizeDelta.x,30);zone.GetComponent<Image>().color=n=="good"?new Color(1,.83f,.08f):new Color(.18f,.92f,.33f);}var label=Ref<TMP_Text>(gauge,"label");Place(label.transform,BC,0,-24,400,25);Text(label.transform,20,false,"Body",TextAlignmentOptions.Center);var title=Label(root.transform,"TimingTitle","완성 타이밍",23,true);Place(title.transform,TC,0,-15,300,32,TC);foreach(var image in bar.GetComponentsInChildren<Image>(true))if(image.name=="Needle")image.color=Color.white;}
