 static void NamedIcon(GameObject root){Fonts(root);((RectTransform)root.transform).sizeDelta=new Vector2(64,74);var e=root.GetComponent<LayoutElement>();if(e!=null){e.minWidth=e.preferredWidth=64;e.flexibleWidth=0;}foreach(var t in root.GetComponentsInChildren<TMP_Text>(true))Text(t.transform,t.name=="Name"?17:18,true,"Title",t.alignment);}
 static void Recipe(GameObject root){Fonts(root);foreach(var t in root.GetComponentsInChildren<TMP_Text>(true))Text(t.transform,t.name=="BasePrice"?24:t.name=="Name"?18:t.fontSize,true,t.name=="BasePrice"?"Number":"Title",t.alignment);foreach(var face in root.GetComponentsInChildren<UISurfacePart>(true))face.gameObject.SetActive(false);var image=root.GetComponent<Image>();if(image!=null)image.color=Color.clear;var rule=New(root.transform,"RecipeRule");rule.anchorMin=new Vector2(0,0);rule.anchorMax=new Vector2(1,0);rule.pivot=new Vector2(.5f,0);rule.offsetMin=new Vector2(8,0);rule.offsetMax=new Vector2(-8,1);var line=rule.GetComponent<Image>()??rule.gameObject.AddComponent<Image>();line.color=new Color(.36f,.22f,.11f,.28f);line.raycastTarget=false;var le=rule.GetComponent<LayoutElement>()??rule.gameObject.AddComponent<LayoutElement>();le.ignoreLayout=true;}
